import axios from 'axios';

// Proxy requests through a serverless function to keep the API key secret.
// Deploy the site to Netlify (or another host that supports serverless functions)
// and set the secret there (e.g. `PIXABAY_KEY` in Netlify Site Settings).
// The function is expected at /.netlify/functions/pixabay?q=...
const PROXY_URL = '/.netlify/functions/pixabay';

export function getImagesByQuery(query) {
  return axios
    .get(PROXY_URL, {
      params: { q: query },
    })
    .then(response => response.data);
}
